-- Row-level security: the fourth layer of tenant isolation.
-- See docs/SECURITY.md §1 Layer 3. Generated by scripts/gen-rls-migration.mjs.
--
-- The application connects as a role with neither SUPERUSER nor BYPASSRLS, so
-- these policies apply to it. FORCE ROW LEVEL SECURITY is deliberately NOT set:
-- the table owner stays exempt so migrations, seeding and retention jobs keep
-- cross-tenant access. Those run offline as a privileged role and are not the
-- surface being defended -- a leaked request handler is.

-- ---------------------------------------------------------------------------
-- STRICT: unset tenant => zero rows. Fails closed.
-- ---------------------------------------------------------------------------
ALTER TABLE "audit_logs" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "audit_logs";
CREATE POLICY tenant_isolation ON "audit_logs"
  USING ("organizationId" = NULLIF(current_setting('app.current_org_id', true), '')::uuid)
  WITH CHECK ("organizationId" = NULLIF(current_setting('app.current_org_id', true), '')::uuid);

