-- ---------------------------------------------------------------------------
-- BOOTSTRAP: readable while resolving which tenant a request belongs to,
-- restricted the moment a tenant is bound.
-- ---------------------------------------------------------------------------
ALTER TABLE "invitations" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "invitations";
CREATE POLICY tenant_isolation ON "invitations"
  USING (
    NULLIF(current_setting('app.current_org_id', true), '') IS NULL
    OR "organizationId" = NULLIF(current_setting('app.current_org_id', true), '')::uuid
  )
  WITH CHECK (
    NULLIF(current_setting('app.current_org_id', true), '') IS NULL
    OR "organizationId" = NULLIF(current_setting('app.current_org_id', true), '')::uuid
  );

