-- ---------------------------------------------------------------------------
-- Join table: no organization_id of its own, scoped through its membership.
-- ---------------------------------------------------------------------------
ALTER TABLE "membership_roles" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "membership_roles";
CREATE POLICY tenant_isolation ON "membership_roles"
  USING (
    NULLIF(current_setting('app.current_org_id', true), '') IS NULL
    OR EXISTS (
      SELECT 1 FROM memberships m
      WHERE m."id" = "membershipId"
        AND m."organizationId" = NULLIF(current_setting('app.current_org_id', true), '')::uuid
    )
  );

-- ---------------------------------------------------------------------------
-- Append-only tables. Application discipline is not a guarantee:
-- docs/OPEN-QUESTIONS.md A-8.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION refuse_mutation() RETURNS trigger AS $$
BEGIN
  -- The owner retains UPDATE/DELETE so retention purges and restores remain
  -- possible. The application role never does.
  IF current_user = 'referral_app' THEN
    RAISE EXCEPTION '% is append-only; % is not permitted', TG_TABLE_NAME, TG_OP
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

REVOKE UPDATE, DELETE ON "audit_logs" FROM referral_app;
DROP TRIGGER IF EXISTS refuse_mutation ON "audit_logs";
CREATE TRIGGER refuse_mutation BEFORE UPDATE OR DELETE ON "audit_logs"
  FOR EACH ROW EXECUTE FUNCTION refuse_mutation();

REVOKE UPDATE, DELETE ON "referral_status_history" FROM referral_app;
DROP TRIGGER IF EXISTS refuse_mutation ON "referral_status_history";
CREATE TRIGGER refuse_mutation BEFORE UPDATE OR DELETE ON "referral_status_history"
  FOR EACH ROW EXECUTE FUNCTION refuse_mutation();

REVOKE UPDATE, DELETE ON "referral_activities" FROM referral_app;
DROP TRIGGER IF EXISTS refuse_mutation ON "referral_activities";
CREATE TRIGGER refuse_mutation BEFORE UPDATE OR DELETE ON "referral_activities"
  FOR EACH ROW EXECUTE FUNCTION refuse_mutation();

-- Ensure the app role can reach tables created by this and future migrations.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO referral_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO referral_app;
REVOKE UPDATE, DELETE ON "audit_logs" FROM referral_app;
REVOKE UPDATE, DELETE ON "referral_status_history" FROM referral_app;
REVOKE UPDATE, DELETE ON "referral_activities" FROM referral_app;
